#[path="../../../../../../../../../../../../../../🧰️framework/🔨️modules/🌱️value/📽️projection/👁️post/🧪️testing/🦀️.rs"]
mod post_fixture;
use post_fixture::PostFixture;
use super::*;
use crate::{PageLayersDelta,PageLayersModification,PageLayerRemoval,PageLayerInsertion,PageLayerRelocation,LayerPatch};
use semio_s_artifact_layout_layout_model::Layer;
use semio_framework_os_kernel as protocol;
use super::super::setters::OwnedPatch;
use protocol::{RetainedDiffApply,RetainedDiffPreflightAdvance,MutationMessage};
use semio_framework_value::retained_clone::RetainedCloneSource;
#[derive(Clone,Default,semio_framework_value_derive::ToValue,semio_framework_value_derive::FromValue,semio_framework_value::RetireOwned,semio_framework_value::RetainedClone)]
struct TestDiff{delta:PageLayersDelta}
impl protocol::MutationDiff<Vec<Layer>> for TestDiff{}
impl protocol::RetainedDiff<Vec<Layer>> for TestDiff{type Apply=TestApply;}
struct TestApply{inner:RetainedCollection<Layer,PageLayersDelta>,membership:bool,index:usize,field:usize}
fn selected(d:RetainedCloneRef<'_,TestDiff>)->RetainedCloneRef<'_,PageLayersDelta>{d.project(0,|diff|&diff.delta)}
impl RetainedDiffApply<Vec<Layer>,TestDiff> for TestApply{
 fn new()->Self{Self{inner:RetainedCollection::new(),membership:false,index:0,field:0}}
 fn preflight_demand(&self,d:RetainedCloneRef<'_,TestDiff>,_:RetainedCloneRef<'_,Vec<Layer>>,post:RetainedCloneRef<'_, Vec<Layer>>,body:usize)->Result<RetirementDemand,ValueError>{self.inner.preflight_demand(selected(d),post.get(),body)}
 fn preflight(&mut self,d:RetainedCloneRef<'_,TestDiff>,_:RetainedCloneRef<'_,Vec<Layer>>,post:RetainedCloneRef<'_, Vec<Layer>>,body:usize,g:RetainedCloneGrant,receiving:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<RetainedDiffPreflightAdvance,ValueError>{let demand=self.inner.preflight_demand(selected(d),post.get(),body)?;if !protocol::retained_mutation_demand_fits(demand,g){return Ok(RetainedDiffPreflightAdvance::Progress(Default::default()))}receiving.checkpoint()?;let step=self.inner.preflight(selected(d),post.get(),body,g)?;assert!(step.error.is_none(),"positive collection witness must admit");Ok(if step.done{RetainedDiffPreflightAdvance::Ready(step.progress,true)}else{RetainedDiffPreflightAdvance::Progress(step.progress)})}
 fn take_messages(&mut self)->Vec<MutationMessage>{Vec::new()}
 fn commit_demand(&self,_:RetainedCloneRef<'_,TestDiff>,_:RetainedCloneRef<'_,Vec<Layer>>,_:&Vec<Layer>,_:usize)->Result<RetirementDemand,ValueError>{if !self.membership{return self.inner.membership_commit_demand()}if self.index==self.inner.modification_targets().unwrap().len(){return Ok(RetirementDemand{copy_bytes:128,depth:1,..Default::default()})}self.inner.staged().unwrap().modified[self.index].patch.field_demand(self.field)}
 fn commit(&mut self,_:RetainedCloneRef<'_,TestDiff>,_:RetainedCloneRef<'_,Vec<Layer>>,post:&mut Vec<Layer>,g:RetainedCloneGrant,capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{if !self.membership{let step=self.inner.commit_membership(post,g,capability)?;if matches!(step,RetainedCloneStep::Complete(_)){self.membership=true}return Ok(RetainedCloneStep::Progress(step.progress()))}let targets=self.inner.modification_targets().unwrap();if self.index==targets.len(){let d=RetirementDemand{copy_bytes:128,depth:1,..Default::default()};return Ok(if protocol::retained_mutation_demand_fits(d,g){RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()})}else{RetainedCloneStep::Progress(Default::default())})}let target=targets[self.index];let patch=&mut self.inner.staged_mut(capability)?.modified[self.index].patch;let d=patch.field_demand(self.field)?;if !protocol::retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()))}let step=patch.exchange_field(&mut post[target],self.field,g,capability)?;self.field+=1;if self.field==<LayerPatch as OwnedPatch<Layer>>::FIELD_COUNT{self.field=0;self.index+=1}Ok(RetainedCloneStep::Progress(step.progress()))}

 fn begin_close(&mut self){self.inner.begin_close()}fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.inner.close_demand(body)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.inner.close_step(g)}fn terminal_is_empty(&self)->bool{self.inner.terminal_is_empty()}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{match RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096}){Ok((owner,_))=>owner,Err((error,_,_))=>panic!("{error}")}}
fn close_source<T:RetireOwned+Sync+'static>(owner:&mut RetainedCloneSource<T>){while !owner.terminal_is_empty(){let d=RetirementDemand{copy_bytes:owner.next_close_copy_byte_demand().unwrap(),capacity_bytes:owner.next_close_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_close_release_byte_demand().unwrap(),depth:owner.next_close_depth_demand().unwrap()};owner.close_step(grant(d)).unwrap();}}
fn close(owner:&mut protocol::RetainedDiffOwner<Vec<Layer>,TestDiff>){owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){return}let d=owner.close_demand(4096).unwrap();assert_eq!(owner.close_step(Default::default()).unwrap().progress(),Default::default());owner.close_step(grant(d)).unwrap();}panic!("real collection central close stalled")}
fn layer(id:&str)->Layer{Layer{id:id.into(),name:format!("name:{id}"),visible:true,locked:false,object_ids:vec![format!("untouched:{id}")]}}
fn input(row:&serde_json::Value)->(Vec<Layer>,TestDiff){let held=row["held"].as_array().unwrap().iter().map(|id|layer(id.as_str().unwrap())).collect();let d=&row["delta"];let delta=PageLayersDelta{removed:d["removed"].as_array().unwrap().iter().map(|row|PageLayerRemoval{id:row["id"].as_str().unwrap().into(),index:row["index"].as_u64().unwrap() as usize}).collect(),inserted:d["inserted"].as_array().unwrap().iter().map(|row|PageLayerInsertion{index:row["index"].as_u64().unwrap() as usize,row:layer(row["id"].as_str().unwrap())}).collect(),moved:d["moved"].as_array().unwrap().iter().map(|row|PageLayerRelocation{id:row["id"].as_str().unwrap().into(),from:row["from"].as_u64().unwrap() as usize,to:row["to"].as_u64().unwrap() as usize}).collect(),modified:d["modified"].as_array().unwrap().iter().enumerate().map(|(i,row)|PageLayersModification{id:row["id"].as_str().unwrap().into(),patch:LayerPatch{name:Some(format!("authored:{i}")),..Default::default()}}).collect()};(held,TestDiff{delta})}
#[test]
fn genuine_central_sparse_collection_keeps_sources_and_untouched_live_allocations(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../📋️keyed-plan/🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){if row.get("error").is_some(){continue}for body in[1024,4096]{let(post,event)=input(row);let mut post=PostFixture::new(post);let pointers:Vec<_>=post.iter().map(|row|row.object_ids[0].as_ptr()).collect();let original=post.clone();let mut base=source(original.clone());let event_copy=event.clone();let mut diff=source(event);let(mut owner,_)=protocol::begin_retained_diff::<Vec<Layer>,TestDiff>(grant(protocol::retained_diff_birth_demand::<Vec<Layer>,TestDiff>())).unwrap();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);for turn in 0..100000{let d=owner.preflight_demand(diff.borrow(),base.borrow(),post.borrow(),body).unwrap();assert_eq!(protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),body,Default::default(),&mut receiving).unwrap().progress(),Default::default());let step=protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),body,grant(d),&mut receiving).unwrap();assert!(step.progress().fits(grant(d)));assert_eq!(post,original);if matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)){break}assert!(turn<99999)}for turn in 0..100000{let d=owner.commit_demand(diff.borrow(),base.borrow(),post.mutable_read(),body).unwrap();assert_eq!(protocol::commit_retained_diff(&mut owner,diff.borrow(),base.borrow(),&mut post,Default::default()).unwrap().progress(),Default::default());let step=protocol::commit_retained_diff(&mut owner,diff.borrow(),base.borrow(),&mut post,grant(d)).unwrap();assert!(step.progress().fits(grant(d)));if matches!(step,RetainedCloneStep::Complete(_)){break}assert!(turn<99999)}for(at,origin)in post.iter().zip(row["origins"].as_array().unwrap()){let expected=if origin[0]=="held"{row["held"][origin[1].as_u64().unwrap() as usize].as_str().unwrap()}else{row["delta"]["inserted"][origin[1].as_u64().unwrap() as usize]["id"].as_str().unwrap()};assert_eq!(at.id,expected);if origin[0]=="held"{assert_eq!(at.object_ids[0].as_ptr(),pointers[origin[1].as_u64().unwrap() as usize])}}for(index,target)in row["modTargets"].as_array().unwrap().iter().enumerate(){let target=target.as_u64().unwrap() as usize;if !row["modTargets"].as_array().unwrap()[index+1..].contains(&serde_json::json!(target)){assert_eq!(post[target].name,format!("authored:{index}"))}}assert_eq!(base.borrow().get(),&original);assert_eq!(diff.borrow().get().delta,event_copy.delta);close(&mut owner);close_source(&mut diff);close_source(&mut base);let mut final_source=source(post.into_inner());close_source(&mut final_source);}}}
